// The entry files of a draft version, generated from its layout and its options.

import type { DraftOption } from '../../shared/index.ts';
import { pascalCase } from './names.ts';

const BANNER =
  '// Generated by kitvas from md/layout.md. Do not edit: change the layout and run "kitvas layout".';

const OPTIONS_BANNER =
  '// Generated by kitvas from src/json/options.json. Do not edit: change the options and run "kitvas layout".';

/**
 * `index.tsx`. With options, `Draft` takes them beside the state and hands both to every section
 * as a spread: a section that reads no option keeps `{ state: string }` and still passes the type
 * check, which a named `options` attribute would fail. Without, the file is the one an older
 * version has.
 */
export function entryTsx(sections: { id: string }[], options: readonly DraftOption[] = []): string {
  const names = sections.map((section) => pascalCase(section.id));
  const withOptions = options.length > 0;
  const props = withOptions ? ' {...props}' : ' state={state}';
  return [
    BANNER,
    ...(withOptions ? ["import type { Options } from './options.ts';"] : []),
    ...names.map((name) => `import { ${name} } from './sections/${name}.tsx';`),
    '',
    withOptions
      ? 'export type DraftProps = { state: string; options: Options };'
      : 'export type DraftProps = { state: string };',
    '',
    withOptions
      ? 'export function Draft(props: DraftProps) {'
      : 'export function Draft({ state }: DraftProps) {',
    '  return (',
    '    <>',
    ...names.map((name) => `      <${name}${props} />`),
    '    </>',
    '  );',
    '}',
    '',
  ].join('\n');
}

/** `options.ts`: the type of one choice, with the exact values of each option as unions. */
export function optionsTs(options: readonly DraftOption[]): string {
  const fields = options.map((option) => {
    const union = option.values.map((value) => JSON.stringify(value.id)).join(' | ');
    return `${JSON.stringify(option.id)}: ${union}`;
  });
  return [OPTIONS_BANNER, `export type Options = { ${fields.join('; ')} };`, ''].join('\n');
}

export function entryScss(sections: { id: string }[]): string {
  return [BANNER, ...sections.map((section) => `@use 'sections/${section.id}';`), ''].join('\n');
}
